import { Youtube, Instagram, Mail, ArrowUpRight } from 'lucide-react';
import { CONTACT } from '@/constants/testIds/portfolio';
import { CHANNEL_URL } from '@/data/films';
import { FadeUp } from './Reveal';

const EMAIL = 'sri20srini09@gmail.com';

const socials = [
  { icon: Youtube, label: 'YouTube', href: CHANNEL_URL },
  { icon: Instagram, label: 'Instagram', href: CHANNEL_URL },
  { icon: Mail, label: 'Email', href: `mailto:${EMAIL}` },
];

export const Contact = () => {
  return (
    <section id="contact" data-testid={CONTACT.section} className="relative px-6 md:px-12 py-28 md:py-40 overflow-hidden">
      <span
        aria-hidden="true"
        className="pointer-events-none select-none absolute top-0 left-1/2 -translate-x-1/2 font-display font-semibold text-[26vw] leading-none uppercase text-white/[0.035] whitespace-nowrap"
      >
        Contact
      </span>

      <div className="relative flex flex-col items-center text-center max-w-3xl mx-auto">
        <FadeUp>
          <span className="inline-flex items-center gap-2 border border-white/15 rounded-full px-4 py-1.5 text-[11px] tracking-[0.25em] uppercase text-white/60">
            <span className="w-1.5 h-1.5 rounded-full bg-[#E11D48] animate-pulse" />
            Open for collaborations
          </span>
        </FadeUp>

        <FadeUp delay={0.1}>
          <h2 className="font-display font-semibold text-5xl md:text-8xl uppercase leading-[0.92] mt-8">
            Got a story<br />in mind?
          </h2>
        </FadeUp>

        <FadeUp delay={0.18}>
          <p className="mt-8 text-white/60 leading-relaxed max-w-md mx-auto">
            Got a script, a collaboration, or a wild idea? Drop us a line and let&apos;s make
            something worth watching.
          </p>
        </FadeUp>

        <FadeUp delay={0.26}>
          <a
            href={`mailto:${EMAIL}`}
            data-testid={CONTACT.submit}
            className="group mt-10 inline-flex items-center gap-3 bg-white text-black rounded-full pl-8 pr-6 py-4 text-xs tracking-[0.25em] uppercase font-medium hover:bg-[#E11D48] hover:text-white transition-colors duration-300"
          >
            Email Us
            <ArrowUpRight className="w-4 h-4 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform duration-300" />
          </a>
        </FadeUp>

        <FadeUp delay={0.34}>
          <div className="mt-14 flex items-center justify-center gap-8 flex-wrap">
            {socials.map((s) => {
              const Icon = s.icon;
              return (
                <a
                  key={s.label}
                  href={s.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  data-testid={`contact-social-${s.label.toLowerCase()}`}
                  className="group flex items-center gap-2 text-white/60 hover:text-white transition-colors duration-300"
                >
                  <Icon className="w-4 h-4 group-hover:text-[#E11D48] transition-colors duration-300" strokeWidth={1.5} />
                  <span className="text-xs tracking-[0.15em] uppercase">{s.label}</span>
                </a>
              );
            })}
          </div>
        </FadeUp>
      </div>
    </section>
  );
};
